const r1 = await search({ query: "terminal" });
const r2 = await search({ query: "command run host" });
const r3 = await search({ query: "shell", limit: 30 });
return JSON.stringify({ terminal: r1.items, command: r2.items, shell: r3.items.map(i => i.path) }, null, 2);

