const base = "http://the VM's public address:18082";
async function getJson(path) {
  const r = await fetch(base + path, { signal: AbortSignal.timeout(30000) });
  const text = await r.text();
  let body; try { body = JSON.parse(text); } catch { body = text; }
  return { status: r.status, body };
}
const [v1, v2first, v2limit5] = await Promise.all([
  getJson("/v1/disbursements"),
  getJson("/v2/disbursements"),
  getJson("/v2/disbursements?limit=5"),
]);
function summarize(v) {
  if (!v || typeof v.body !== "object" || !Array.isArray(v.body.disbursements)) return { status: v?.status, body: v?.body };
  const b = v.body;
  return {
    status: v.status,
    count: b.disbursements.length,
    cursor: b.cursor,
    drained: b.drained,
    first: b.disbursements[0],
    last: b.disbursements[b.disbursements.length - 1],
  };
}
return JSON.stringify({ v1: summarize(v1), v2first: summarize(v2first), v2limit5: summarize(v2limit5) }, null, 2);

