const probe = `
import json, urllib.request
base="http://the VM's public address:18082"
def get(p):
    with urllib.request.urlopen(base+p, timeout=30) as r:
        return r.status, json.load(r)
s1, b1 = get("/v1/disbursements")
print("v1:", s1, len(b1["disbursements"]))
print("v1 first:", json.dumps(b1["disbursements"][0]))
print("v1 last: ", json.dumps(b1["disbursements"][-1]))
s2, b2 = get("/v2/disbursements")
print("v2 full:", s2, len(b2["disbursements"]), "drained:", b2["drained"], "cursor:", b2["cursor"][:40])
print("v2 first:", json.dumps(b2["disbursements"][0]))
print("v2 [1]:  ", json.dumps(b2["disbursements"][1]))
s3, b3 = get("/v2/disbursements?limit=5")
print("v2 limit5:", s3, len(b3["disbursements"]), "drained:", b3["drained"])
print("v2 limit5 last:", json.dumps(b3["disbursements"][-1]))
`;
const r = await tools.microsandbox.sandbox_run({
  image: "python:3.12-slim",
  command: "python3 - <<'EOF'\n" + probe + "\nEOF",
});
return JSON.stringify(r, null, 2);

